# -*- coding: utf-8 -*-
import copy
import ca50_gaps as G
from ca50_gaps import L
h,rs,t=G.load();r=next(r for r in rs if r['id']=='dalhousie-university');D='2026-10-26';src='https://www.dal.ca/admissions/scholarships-financial-aid/scholarships/future-undergraduate-student-awards.html'
a=r['scholarships']['merit'][0];assert a['name']=='Dalhousie General Entrance Awards'
a.update(G.plain({'id':'general-entrance-awards','category':'merit','entryTerm':'Autumn','entryYear':'2027','verified':D,'eligibility':L('Domestic and international Fall entrants directly from high school or without transferable post-secondary study; normally 80% across the five programme-required courses or 26 predicted IB points, with named exceptions','Иностранные и местные поступающие осенью непосредственно из школы либо без зачётного post-secondary обучения; обычно 80% по пяти предметам программы или 26 predicted IB points, с опубликованными исключениями'),'note':L('The 2027–28 programme opens 1 October 2026 and requires the award application and required documents by 15 February 2027. Apply for undergraduate admission first; an offer need not already have been issued. Official first-semester transcripts must be sent by the issuing institution; extra financial or other evidence depends on the award. Awards may be one-time or renewable for up to four years; no common amount or guaranteed full funding is stated.','Программа 2027–28 открывается 1 октября 2026 и требует стипендиальную заявку и необходимые документы до 15 февраля 2027. Сначала подаётся undergraduate admission; готовый offer заранее не обязателен. Официальную выписку первого семестра направляет выдавшее учреждение; дополнительные финансовые и другие документы зависят от award. Выплаты бывают однократными или продлеваемыми до четырёх лет; общей суммы или гарантированного полного покрытия нет.')}))
d=next(d for d in r['admissions']['deadlines'] if d['kind']=='scholarship' and 'General Entrance' in d['name'])
d.pop('binding',None);d.update(G.plain({'awardId':a['id'],'awardCategory':a['category'],'verified':D,'cycleEvidence':{'basis':'page-context','entryTerm':'Autumn','entryYear':'2027','source':src,'verified':D,'quote':'2027–2028 General Entrance Award program'},'conditions':L('Fall school-leavers or applicants without transferable post-secondary study. Submit the admission application before the award application. Required documents must also arrive by this deadline.','Осенние school-leavers либо поступающие без зачётного post-secondary обучения. Admission application подаётся до стипендиальной заявки. Необходимые документы тоже должны поступить к этому сроку.')}))
if not any(x.get('awardId')==a['id'] and x['kind']=='documents' for x in r['admissions']['deadlines']):
 docs=copy.deepcopy(d);docs.update(G.plain({'kind':'documents','name':L('General Entrance Awards — required documents','General Entrance Awards — необходимые документы')}));r['admissions']['deadlines'].append(docs)
if not any(x['name']=='Murray Family Jamaican Engineering Scholarship' for x in r['scholarships']['merit']):
 r['scholarships']['merit'].append(G.plain({'name':'Murray Family Jamaican Engineering Scholarship','amount':L('C$88,000 (C$22,000 renewable for four years)','C$88,000 (C$22,000 с продлением на четыре года)'),'eligibility':L('Students from Jamaica entering Bachelor of Engineering, with preference for Civil Engineering, showing good academic standing and financial need','Студенты из Ямайки, поступающие на Bachelor of Engineering; предпочтение Civil Engineering, хорошие результаты и финансовая нуждаемость'),'deadline':None,'application':L('Consideration through the General Entrance Award application; this is not an unrestricted international award','Рассмотрение через General Entrance Award application; это не award для всех иностранцев'),'renewable':True,'note':L('The individual listing does not establish a separate Fall 2027 deadline or all renewal thresholds. No tuition/living coverage percentage is inferred from the cash amount, and it is not subtracted as awarded aid.','Отдельное описание не устанавливает самостоятельный срок Fall 2027 или все пороги продления. Из денежной суммы не выводится процент покрытия обучения/жизни; она не вычитается как уже полученная помощь.'),'basis':'need-merit','source':src,'verified':D}))
G.save(h,rs,t);G.flush()
